INSERT INTO produtos (id, nome, descricao, categoria, preco, foto, tamanhos, cores, ativo, ordem) VALUES
  ('prd-foto-01', 'Conjunto Saia Ruffled com Fenda Drapeada e Top Frente Única', 'Conjunto leve e moderno composto por top cropped de gola alta/frente única e mini saia com drapeado ajustável, detalhe de broche dourado e faixa fluida caída. Confeccionado em tecido leve e levemente transparente, ideal para ocasiões e festas de verão.', 'Conjuntos', 130.90, 'img/produtos/produto-01.jpeg', '["P","M","G"]', '["Azul Bebê"]', 1, 0),
  ('prd-foto-02', 'Conjunto Corset Tomara que Caia com Peplum e Short Alfaiataria', 'Conjunto elegante e estruturado composto por top estilo corset tomara que caia com babado peplum na barra e shorts de cintura alta com corte limpo. Perfeito para eventos casuais refinados e composições sofisticadas.', 'Conjuntos', 179.90, 'img/produtos/produto-02.jpeg', '["P","M","G"]', '["Off White"]', 1, 1),
  ('prd-foto-03', 'Conjunto Tricô Cropped com Flor e Mini Saia', 'Conjunto em tricô trabalhado na cor rosa choque, composto por top cropped com detalhe tridimensional de flor na alça e mini saia com cordão de amarração na cintura. Casual, moderno e muito charmoso.', 'Conjuntos', 122.90, 'img/produtos/produto-03.jpeg', '["P","M","G"]', '["Pink"]', 1, 2),
  ('prd-foto-04', 'Conjunto Top Degagê com Flor e Mini Saia Drapeada', 'Conjunto vibrante na cor laranja, com top de decote degagê (drapeado no peito), aplique floral na alça e saia justa com leve drapeado. Ideal para um visual marcante e noites quentes.', 'Conjuntos', 167.90, 'img/produtos/produto-04.jpeg', '["P","M","G"]', '["Laranja"]', 1, 3),
  ('prd-foto-05', 'Corset Tomara que Caia Acetinado', 'Top corset estruturado com barbatanas aparentes e acabamento acetinado no tom verde menta. Uma peça versátil e sensual que combina perfeitamente com shorts jeans de cintura alta ou calças de alfaiataria.', 'Corsets', 189.90, 'img/produtos/produto-05.jpeg', '["P","M","G"]', '["Verde Menta"]', 1, 4),
  ('prd-foto-06', 'Vestido Mídi Canelado Listras Verticais', 'Vestido ajustado ao corpo de comprimento mídi, confeccionado em malha canelada com listras verticais em preto e branco. Possui alças finas e valoriza a silhueta de forma elegante e confortável.', 'Vestidos', 182.90, 'img/produtos/produto-06.jpeg', '["P","M","G"]', '["Preto e Branco"]', 1, 5),
  ('prd-foto-07', 'Conjunto Tricô Listrado Cropped e Shorts', 'Conjunto casual de tricô macio com listras horizontais largas nas cores preto e branco. Composto por regata cropped de decote U e shorts de cintura alta com cordão de ajuste.', 'Conjuntos', 140.90, 'img/produtos/produto-07.jpeg', '["P","M","G"]', '["Preto e Branco"]', 1, 6),
  ('prd-foto-08', 'Conjunto Top Degagê com Flor e Mini Saia', 'Conjunto minimalista e sofisticado na cor preta, composto por top de decote drapeado degagê com detalhe floral na alça e mini saia justa de cintura alta.', 'Conjuntos', 154.90, 'img/produtos/produto-08.jpeg', '["P","M","G"]', '["Preto"]', 1, 7),
  ('prd-foto-09', 'Conjunto Canelado Listrado Cropped Manga Curta e Saia Mídi', 'Conjunto feminino em malha canelada com estampa de listras horizontais em rosa e branco. Acompanha blusa cropped de manga curta e gola alta com saia de comprimento mídi e fenda discreta.', 'Conjuntos', 139.90, 'img/produtos/produto-09.jpeg', '["P","M","G"]', '["Rosa e Branco"]', 1, 8),
  ('prd-foto-10', 'Conjunto Tricô Modal Cut-Out com Franjas', 'Conjunto em tricô modal na cor verde oliva/pistache, com top de amarração no pescoço e detalhe central de contas de madeira, combinado com saia de cintura alta finalizada com acabamento em franjas na barra. Estilo praiano e boho chic.', 'Conjuntos', 185.90, 'img/produtos/produto-10.jpeg', '["P","M","G"]', '["Verde Oliva"]', 1, 9),
  ('prd-foto-11', 'Corset Bojo com Barra Recortada em Bico', 'Top corset estruturado com bojo, alças finas e acabamento em bordado inglês recortado em bico no decote e na barra. Delicado e romântico, fica lindo com shorts jeans de cintura alta para um visual leve de verão.', 'Corsets', 170.90, 'img/produtos/produto-11.jpeg', '["P","M","G"]', '["Branco"]', 1, 10),
  ('prd-foto-12', 'Conjunto Tricô Listrado Regata e Saia Longa', 'Conjunto em tricô canelado com listras horizontais largas nas cores amarelo, bege e marrom. Composto por regata cropped com amarração no ombro e saia longa ajustada ao corpo. Confortável, elegante e perfeito para passeios e eventos diurnos.', 'Conjuntos', 112.90, 'img/produtos/produto-12.jpeg', '["P","M","G"]', '["Amarelo, Bege e Marrom"]', 1, 11),
  ('prd-foto-13', 'Conjunto Corset Listrado Limões e Shorts', 'Conjunto alegre em tecido listrado amarelo e branco com estampa de limões-sicilianos. Composto por top corset com alças finas e barra em bico e shorts de cintura alta com botões frontais e bolsos. Fresco e divertido, ideal para dias de sol.', 'Conjuntos', 136.90, 'img/produtos/produto-13.jpeg', '["P","M","G"]', '["Amarelo e Branco"]', 1, 12),
  ('prd-foto-14', 'Vestido Curto Frente Única Decote Drapeado com Franzido Lateral', 'Vestido curto e ajustado em malha com elastano, decote drapeado profundo e alças frente única com detalhes metálicos dourados. Franzido lateral com cordão de regulagem na barra, que valoriza as curvas. Marcante e sensual, ideal para festas e noites especiais.', 'Vestidos', 111.90, 'img/produtos/produto-14.jpeg', '["P","M","G"]', '["Laranja"]', 1, 13),
  ('prd-foto-15', 'Conjunto Atoalhado Jacquard Top Cortininha e Calça Pantalona', 'Conjunto em tecido atoalhado com textura jacquard geométrica em tons de rosa. Composto por top cortininha com amarração no pescoço e calça pantalona de cintura elástica com cordão e bolsos. Despojado e confortável, perfeito para looks de praia e resort.', 'Conjuntos', 119.90, 'img/produtos/produto-15.jpeg', '["P","M","G"]', '["Rosa"]', 1, 14),
  ('prd-foto-16', 'Conjunto Top com Renda e Shorts Floral', 'Conjunto em malha macia verde lima com delicados bordados florais. Composto por top de alças finas com acabamento em renda branca e babado na barra, e shorts de cintura elástica. Leve, feminino e confortável para o dia a dia.', 'Conjuntos', 174.90, 'img/produtos/produto-16.jpeg', '["P","M","G"]', '["Verde Lima"]', 1, 15);
